package dndcharacter

import (
	"math/rand"
	"sort"
)

type Character struct {
	Strength     int
	Dexterity    int
	Constitution int
	Intelligence int
	Wisdom       int
	Charisma     int
	Hitpoints    int
}

// Modifier calculates the ability modifier for a given ability score.
// It subtracts 10 from the score, divides by 2 and rounds down (floor).
func Modifier(score int) int {
	diff := score - 10
	mod := diff / 2
	if diff < 0 && diff%2 != 0 {
		mod-- // floor, since Go truncates toward zero
	}
	return mod
}

// Ability uses randomness to generate the score for an ability:
// roll four 6-sided dice and sum the largest three.
func Ability() int {
	dice := make([]int, 4)
	for i := range dice {
		dice[i] = rand.Intn(6) + 1
	}
	sort.Ints(dice)
	return dice[1] + dice[2] + dice[3]
}

// GenerateCharacter creates a new Character with random scores for abilities.
func GenerateCharacter() Character {
	constitution := Ability()
	return Character{
		Strength:     Ability(),
		Dexterity:    Ability(),
		Constitution: constitution,
		Intelligence: Ability(),
		Wisdom:       Ability(),
		Charisma:     Ability(),
		Hitpoints:    10 + Modifier(constitution),
	}
}
